        background: var(--default-hover-bg, var(--body-bg));
      }
    }

    :deep(.split-btn__main) { width: 22px; }

    :deep(.split-btn__more) {
      width:     14px;
      padding:   0;
      font-size: 9px;
    }
  }

  &__new {
    flex: 0 0 auto;
    display: flex;
    align-items: center;
    justify-content: center;
    width: 28px;
    min-height: 32px;
    margin: 2px 0;
